import { matchPath } from "../../utils/url";

export const isCandidateUrl = (url = window.location.href): boolean => {
  const parsedUrl = new URL(url);
  return (
    !!parsedUrl.searchParams.get("candidate_id") ||
    !!matchPath("/candidate/<candidate_id>", parsedUrl.pathname) ||
    !!matchPath("/candidate/<candidate_id>/*", parsedUrl.pathname) ||
    !!matchPath(
      "/ats/jobs/<job_id>/candidates/<candidate_id>",
      parsedUrl.pathname,
    )
  );
};

export const isInterviewScorecardUrl = (
  url = window.location.href,
): boolean => {
  const parsedUrl = new URL(url);
  return !!matchPath(
    "/ats/interviews/<interview_id>/scorecard",
    parsedUrl.pathname,
  );
};

