import { MutationSummary } from "./MutationSummary";

type QueryElParams = {
  selector: string;
  rootNode?: ParentNode;
  timeout?: number;
};

export const queryEl = async <T extends Element = Element>({
  selector,
  rootNode = document,
  timeout = 10_000,
}: QueryElParams): Promise<T | null> => {
  const el = rootNode.querySelector<T>(selector);
  if (el) return el;

  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      resolve(null);
      obs.disconnect();
    }, timeout);

    const obs = new MutationSummary({
      rootNode,
      queries: [{ element: selector }],
      callback: ([{ added }]) => {
        const el = added[0] as T;
        if (el) {
          resolve(el);
          obs.disconnect();
          clearTimeout(timer);
        }
      },
    });
  });
};

export const queryEls = async <T extends Element = Element>({
  selector,
  rootNode = document,
  timeout = 10_000,
}: QueryElParams): Promise<T[]> => {
  const els = rootNode.querySelectorAll<T>(selector);
  if (els && els.length > 0) return Array.from(els);

  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      resolve([]);
      obs.disconnect();
    }, timeout);

    const obs = new MutationSummary({
      rootNode,
      queries: [{ element: selector }],
      callback: ([{ added }]) => {
        if (added.length > 0) {
          resolve(added as T[]);
          obs.disconnect();
          clearTimeout(timer);
        }
      },
    });
  });
};
