/**
 * Handles showing and hiding the BrightHire sidepanel across all Gem pages
 */
import { BRIGHTHIRE_ID } from "../../utils/calendarButton";
import { setupCloseButtons, setupDrawer } from "../../utils/drawer";
import { sendMessageWithTabId } from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { isAtsCallButtonHidden } from "../../utils/orgSettings";
import { queryEl, queryEls } from "../../utils/query";
import { emailRegex, phoneNumberRegex } from "../../utils/regex";
import { getUiConfig } from "../../utils/ui-config";
import { FALLBACK_CONFIG } from "../../utils/ui-config/UI_CONFIG";
import { buildUrl } from "../../utils/url";
import { BUTTON_STYLE } from "../style";

let SELECTORS = FALLBACK_CONFIG.gem;

const buildBrightHireButton = async (
  phoneNumber: string,
  email?: string,
): Promise<HTMLButtonElement> => {
  const brighthireButton = document.createElement("button");
  brighthireButton.id = BRIGHTHIRE_ID;
  brighthireButton.type = "button";
  brighthireButton.setAttribute("style", BUTTON_STYLE);
  brighthireButton.style.height = "34px";
  brighthireButton.style.paddingLeft = "8px";
  brighthireButton.style.paddingRight = "8px";
  brighthireButton.innerText = "Call with BrightHire";
  const url = await buildUrl("/interview-assistant/integrations/gemCandidate", {
    url: window.location.href,
    phoneNumber,
    email: email || "",
  });
  brighthireButton.onclick = () =>
    chrome.runtime.sendMessage({
      action: "openIA",
      payload: { url, windowAvailHeight: window.screen.availHeight },
    });
  return brighthireButton;
};

const getPhoneFromLabel = (label: Node | undefined): string | undefined => {
  const phoneNumber = phoneNumberRegex.exec(
    label?.textContent?.replace(/[\W]/g, "") ?? "",
  )?.[0];
  return phoneNumber;
};

const cleanUpButtons = (baseNode?: HTMLElement | null): void => {
  const existingButtons = (baseNode || document)?.querySelectorAll(
    `#${BRIGHTHIRE_ID}`,
  );
  existingButtons?.forEach((button) => {
    button.remove();
  });
};

const setupCallButton = async (email?: string): Promise<void> => {
  if (await isAtsCallButtonHidden()) return;
  cleanUpButtons();
  const phoneNumberContainers = await queryEls<HTMLDivElement>({
    selector: SELECTORS.phoneNumberLabel,
  });
  const phoneNumber = getPhoneFromLabel(phoneNumberContainers[0]);

  if (phoneNumber) {
    const brightHireButton = await buildBrightHireButton(phoneNumber, email);
    await Promise.all([
      queryEl<HTMLDivElement>({
        selector: SELECTORS.profileHeaderButtons,
      }).then((header) => {
        if (header) {
          cleanUpButtons(header);
          header.insertBefore(brightHireButton, header.firstChild);
        }
      }),
      queryEl<HTMLDivElement>({
        selector: SELECTORS.modalHeader,
      }).then((modalHeader) => {
        const profileHeader = modalHeader?.querySelector<HTMLDivElement>(
          SELECTORS.innerContainer,
        );
        if (profileHeader) {
          cleanUpButtons(profileHeader);
          profileHeader.appendChild(brightHireButton);
        }
      }),
    ]);
  }
};

export const getProfileHeader = (parent?: HTMLElement) => {
  return (parent ?? document).querySelector("[class*=profileHeader]");
};

export const setupCandidatePage = async (): Promise<void> => {
  const emailContainer = await queryEl<HTMLDivElement>({
    selector: SELECTORS.emailLabel,
  });
  const candidateEmail = emailRegex.exec(
    emailContainer?.textContent || "",
  )?.[0];
  const urlParams: Record<string, string> = {
    intent: "Candidate",
  };
  if (candidateEmail) {
    urlParams.email = candidateEmail;
  }
  setupDrawer({
    urlParams,
  }).then((loading) => {
    if (loading) sendMessageWithTabId({ action: "drawerLoading" });
  });
  setupCallButton(candidateEmail);
  setupCloseButtons();
};

const candidateModalObserver = new MutationObserver((mutations) => {
  mutations.forEach((mutation) => {
    if (mutation.type === "childList") {
      mutation.addedNodes.forEach(async (node) => {
        if (node instanceof HTMLDivElement && getProfileHeader(node)) {
          await setupCandidatePage();
        }
      });
    }
  });
});

onDocumentLoaded(async () => {
  const uiConfig = await getUiConfig("gem");
  if (uiConfig) SELECTORS = uiConfig;
  candidateModalObserver.observe(document.body, {
    childList: true,
    subtree: true,
  });
});
