import { getCurrentUser } from "./storage";

const enabledFeaturesForTest: string[] = [];

export const enableFeatureForTest = (featureFlag: string): void => {
  if (process.env.APP_ENV === "test") {
    enabledFeaturesForTest.push(featureFlag);
  }
};

export const resetTestFeatures = (): void => {
  if (process.env.APP_ENV === "test") {
    enabledFeaturesForTest.splice(0, enabledFeaturesForTest.length);
  }
};

export const featureFlagEnabled = async (
  featureFlag: string,
  defaultEnabled = false,
): Promise<boolean> => {
  if (process.env.APP_ENV === "test") {
    return enabledFeaturesForTest.includes(featureFlag);
  }

  const currentUser = await getCurrentUser();
  if (currentUser == null) return defaultEnabled;
  return currentUser.enabledFeatures.includes(featureFlag);
};

export const planEnabled = async (): Promise<boolean> => {
  const currentUser = await getCurrentUser();
  return currentUser?.organization?.planEnabled ?? false;
};

export const showJoinWithBrighthire = async (): Promise<boolean> => {
  const currentUser = await getCurrentUser();
  const status = currentUser?.showJoinWithBrighthire;

  if (status === "SHOW") {
    return true;
  }

  return false;
};

export const inPersonEnabled = async (): Promise<boolean> => {
  const currentUser = await getCurrentUser();
  return currentUser?.organization?.allowInPersonMeetings ?? false;
};

export const isWorkdayOneClickAllFieldsEnabled = async (): Promise<boolean> => {
  const currentUser = await getCurrentUser();
  return !!currentUser?.organization?.workdayOneClickAllFields;
};

export const getWorkdayQuestionnaireTitles = async (): Promise<string[]> => {
  const currentUser = await getCurrentUser();
  return currentUser?.organization?.workdayQuestionnaireTitles ?? [];
};
