import Draggerjs from "draggerjs";

import { featureFlagEnabled } from "./featureFlag";
import { logVerbose } from "./logVerbose";
import {
  addPassiveMessageListener,
  getTabId,
  sendMessageWithTabId,
} from "./message";
import { captureException } from "./sentry";
import { buildUrl } from "./url";

const BH_CLASSNAME_VISIBLE = "brighthire-visible";
const BH_CLASSNAME_DISABLED = "brighthire-disabled";
const BH_TOAST_CONTAINER_POSITION_ITEM = "brighthire-toast-container-position";

const tabIdPromise = getTabId();

const featureEnabledPromise = featureFlagEnabled(
  "browser-extension:side-panel-disabled",
).then((featureDisabled) => !featureDisabled);

/**
 * Drawer where BrightHire application is rendered
 */
let drawer = document.createElement("iframe");
drawer.id = "brighthire-drawer";
drawer.className = "brighthire-drawer";
drawer.allow = "fullscreen *; clipboard-write *;";

/**
 * Tab that opens/closes the drawer
 */
const toastWrapper = document.createElement("div");
toastWrapper.id = "brighthire-toast-wrapper";
toastWrapper.className = "brighthire-toast-wrapper";

/**
 * Inner container for the tab
 */
const toastContainer = document.createElement("div");
toastContainer.id = "brighthire-toast-container";
toastContainer.className = "brighthire-toast-container";

const setInitialToastPosition = (): void => {
  const parentHeight = toastWrapper.clientHeight;
  const toastHeight = toastContainer.clientHeight;

  // default buffer of 60px from bottom of screen
  let position = parentHeight - (toastHeight + 60);
  const savedPosition = parseFloat(
    localStorage.getItem(BH_TOAST_CONTAINER_POSITION_ITEM) || "",
  );

  if (savedPosition && savedPosition + toastHeight < parentHeight) {
    position = savedPosition;
  }

  toastContainer.style.top = `${position}px`;
};

/**
 * Grabber for dragging the tab
 */
const toastGrabber = document.createElement("div");
toastGrabber.id = "brighthire-toast-grabber";
toastGrabber.className = "brighthire-toast-grabber";

/**
 * Iframe for the tab - it is the iframe that does stuff when clicked
 */
const toast = document.createElement("iframe");
toast.id = "brighthire-toast";
toast.className = "brighthire-toast";

export const closeDrawer = (): void => {
  drawer.classList.remove(BH_CLASSNAME_VISIBLE);
};

export const openDrawer = (): void => {
  drawer.classList.add(BH_CLASSNAME_VISIBLE);
};

export const toggleDrawer = (): void => {
  drawer.classList.toggle(BH_CLASSNAME_VISIBLE);
};

export const openDrawerToast = (): void => {
  toast.classList.add(BH_CLASSNAME_VISIBLE);
  toast.parentElement?.classList.add(BH_CLASSNAME_VISIBLE);
  toastGrabber.classList.add(BH_CLASSNAME_VISIBLE);
  toastContainer.classList.add(BH_CLASSNAME_VISIBLE);
};

export const disableDrawerToast = (): void => {
  closeDrawer();
  toast.classList.add(BH_CLASSNAME_DISABLED);
  toastGrabber.classList.add(BH_CLASSNAME_DISABLED);
  toastContainer.classList.add(BH_CLASSNAME_DISABLED);
};

export const enableDrawerToast = (): void => {
  toast.classList.remove(BH_CLASSNAME_DISABLED);
  toastGrabber.classList.remove(BH_CLASSNAME_DISABLED);
  toastContainer.classList.remove(BH_CLASSNAME_DISABLED);
};

export const closeDrawerToast = (): void => {
  closeDrawer();
  toast.classList.remove(BH_CLASSNAME_VISIBLE);
  toast.parentElement?.classList.remove(BH_CLASSNAME_VISIBLE);
  toastGrabber.classList.remove(BH_CLASSNAME_VISIBLE);
  toastContainer.classList.remove(BH_CLASSNAME_VISIBLE);
};

const onMessage: MessageListener = ({ message }) => {
  try {
    switch (message.action) {
      case "openDrawerToast": {
        openDrawerToast();
        break;
      }
      case "disableDrawerToast": {
        disableDrawerToast();
        break;
      }
      case "enableDrawerToast": {
        enableDrawerToast();
        break;
      }
      case "closeDrawerToast": {
        closeDrawerToast();
        break;
      }
      case "openDrawer": {
        openDrawer();
        break;
      }
      case "toggleDrawer": {
        toggleDrawer();
        break;
      }
      case "setToastText": {
        // set the toast's height if `toastHeight` was passed
        const toastHeight = message.payload?.toastHeight;
        if (toastHeight) {
          toastContainer.style.setProperty("height", toastHeight);
        } else {
          toastContainer.style.setProperty("height", null);
        }

        // add the toast notification badge if `toastNotification` was passed
        const toastNotification = message.payload?.toastNotification;
        if (toastNotification === undefined) {
          toastContainer.style.setProperty("--bh-toast-alert", null);
          toastContainer.style.setProperty("--bh-toast-size", null);
        } else {
          toastContainer.style.setProperty(
            "--bh-toast-alert",
            `"${toastNotification}"`,
          );
          toastContainer.classList.remove("bh-notification-large");
          toastContainer.classList.remove("bh-notification");
          if (toastNotification.length > 1) {
            toastContainer.classList.add("bh-notification-large");
          } else if (toastNotification) {
            toastContainer.classList.add("bh-notification");
          }
        }
      }
    }
  } catch (err) {
    captureException(err);
    throw err;
  }
};

let listenerInitialized = false;
export const initListeners = (): void => {
  if (!listenerInitialized) {
    listenerInitialized = true;
    addPassiveMessageListener(onMessage);
  }
};

type SetDrawerSrcParams = {
  tabUrl?: string;
  forceReload?: boolean;
  urlParams?: Record<string, string>;
  layout?: "left" | "right";
};

export const setDrawerSrc = async ({
  tabUrl = window.location.href,
  forceReload,
  urlParams = {},
  layout = "right",
}: SetDrawerSrcParams = {}): Promise<boolean> => {
  const tabId = await tabIdPromise;

  const drawerUrl = chrome.runtime.getURL(`drawer.html`);
  const appUrl = await buildUrl("extension", {
    tabId: tabId?.toString() ?? "",
    tabUrl,
    ...urlParams,
  });

  // pass the BrightHire app url as a param of the drawer url - see drawer.ts
  const drawerSrc = await buildUrl(drawerUrl, {
    appUrl: encodeURIComponent(appUrl.href),
  });

  const reloadTriggered = forceReload || drawerSrc.href !== drawer.src;
  if (reloadTriggered) {
    logVerbose("cloning side panel drawer", drawer);
    const newDrawer = drawer.cloneNode() as HTMLIFrameElement;
    logVerbose("new side panel drawer src", drawerSrc);
    newDrawer.src = drawerSrc.href;
    logVerbose("replacing side panel drawer", drawer, drawerSrc);
    drawer.replaceWith(newDrawer);
    drawer = newDrawer;
  }

  // Anchors the drawer on the left side of the screen
  if (layout === "left") {
    drawer.style.left = "0";
  }

  return reloadTriggered;
};

type AddSidepanelParams = Pick<SetDrawerSrcParams, "layout">;

export const addSidePanel = async ({
  layout,
}: AddSidepanelParams = {}): Promise<void> => {
  const featureEnabled = await featureEnabledPromise;
  if (!featureEnabled) return;

  if (!document.body) return;

  if (document.body.contains(toast)) {
    return;
  }

  logVerbose("adding side panel");
  toast.src = chrome.runtime.getURL("toast.html");
  document.body
    .appendChild(toastWrapper)
    .appendChild(toastContainer)
    .appendChild(toast);
  toastContainer.appendChild(toastGrabber);
  document.body.appendChild(drawer);
  if (window.location.hostname.endsWith("greenhouse.io")) {
    toastWrapper.style.top = "65px";
  }
  setInitialToastPosition();
  // Anchors the toast to left side of screen
  if (layout === "left") {
    toast.style.transform = "rotate(180deg)";
    toastWrapper.style.left = "0";
    toastContainer.style.left = "0";
  }

  const dragger = new Draggerjs("#brighthire-toast-wrapper", {
    axis: "y",
    allowBoundContainer: true,
    draggable: "#brighthire-toast-container",
    autoscroll: true,
  });

  dragger.on("dragstart", (e) => {
    const { target } = e;
    if (e.isDraggableElement) {
      e.preventDefault();
      target.classList.add("grabbed");
      if (target.classList.contains("center")) {
        target.classList.remove("center");
      }
    }
  });

  dragger.on("dragend", (e) => {
    if (e.isDraggableElement) {
      localStorage.setItem(
        BH_TOAST_CONTAINER_POSITION_ITEM,
        toastContainer.style.top,
      );
      e.target.classList.remove("grabbed");
    }
  });
};

/** Reports when the `body` element is removed, which will also remove the sidepanel */
export const onSidepanelRemoved = (): Promise<void> => {
  return new Promise((resolve) => {
    const obs = new MutationObserver((mutations) => {
      const bodyRemoved = mutations
        .flatMap((m) => Array.from(m.removedNodes))
        .some((n) => n.nodeName === "BODY");

      if (bodyRemoved) {
        resolve();
        obs.disconnect();
      }
    });

    obs.observe(document.documentElement, {
      childList: true,
    });
  });
};

/**
 * Main entry point for adding the drawer to the page.
 * Returns a boolean indicating whether or not the drawer was reloaded
 */
export const setupDrawer = (params?: SetDrawerSrcParams): Promise<boolean> => {
  initListeners();
  addSidePanel(params);
  return setDrawerSrc(params);
};

/**
 * Useful when we insert UI / trigger drawer state within modals.
 * Finds close/dismiss buttons on the page and attaches click handlers that
 * reset the drawer to its default state. An optional `onClose` callback is
 * called after the drawer is reset (e.g. to tear down ATS-specific UI).
 */
export const setupCloseButtons = (onClose?: () => void): void => {
  const closeButtons = Array.from(
    document.querySelectorAll<HTMLButtonElement>("button"),
  ).filter(
    (button) =>
      button.textContent === "Close" ||
      button.classList.contains("close") ||
      button.ariaLabel?.includes("cross"),
  );

  closeButtons.forEach((closeButton) => {
    closeButton.addEventListener("click", async () => {
      const loading = await setupDrawer();
      if (loading) sendMessageWithTabId({ action: "drawerLoading" });
      onClose?.();
    });
  });
};
