/**
 * Handles showing and hiding the BrightHire sidepanel across all Gem pages.
 *
 * NOTE: Scorecard setup (including drawer setup with interview intent) is
 * handled by gemScorecardContentScript.ts which detects scorecard modals
 * via MutationObserver. This drawer script handles candidate pages and
 * general pages only.
 */
import { setupDrawer } from "../../utils/drawer";
import {
  addPassiveMessageListener,
  sendMessageWithTabId,
} from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { getProfileHeader, setupCandidatePage } from "./candidate";
import { isCandidateUrl } from "./utils";

const isCandidateVisible = (url?: string) => {
  return isCandidateUrl(url) || !!getProfileHeader();
};

export const setup = async (url?: string) => {
  if (isCandidateVisible(url)) {
    await setupCandidatePage();
  } else {
    await setupDrawer().then((loading) => {
      if (loading) sendMessageWithTabId({ action: "drawerLoading" });
    });
  }
};

onDocumentLoaded(async () => {
  await setup();
  addPassiveMessageListener(async ({ message }) => {
    if (message.action === "tabUrlChanged") {
      await setup(message.payload?.url);
    }
    if (message.action === "loadingComplete") {
      await setup();
    }
  });
});
